impl Solution {
    pub fn minimum_deletions(nums: Vec<i32>) -> i32 {
        let n = nums.len();
        if n == 1 {
            return 1;
        }

        let min_val = *nums.iter().min().unwrap();
        let max_val = *nums.iter().max().unwrap();

        let min_index = nums.iter().position(|&x| x == min_val).unwrap();
        let max_index = nums.iter().position(|&x| x == max_val).unwrap();

        let left_min = min_index + 1;
        let left_max = max_index + 1;
        let right_min = n - min_index;
        let right_max = n - max_index;

        let case1 = left_min + right_max;
        let case2 = left_max + right_min;
        let case3 = std::cmp::max(left_min, left_max);

        std::cmp::min(std::cmp::min(case1, case2), case3)
    }
}

